(1169, '5440', 'BICALUTAMIDA', 'TABLETA', '50 MG', '14 TABLETAS', 'SEGUNDO NIVEL', 'ONCOLOGÍA', 'ANTIANDRÓGENO NO ESTEROIDEO QUE INHIBE COMPETITIVAMENTE AL RECEPTOR ANDROGÉNICO. CUANDO SE HA USADO COMO MONOFÁRMACO SE HA OBSERVADO AUMENTO DE LA TESTOSTERONA Y EL ESTRADIOL SÉRICOS, POR LO QUE SE DEBE ADMINISTRAR EN FORMA CONCOMITANTE CON LHRH.', 'X', 'ENROJECIMIENTO FACIAL, DIAFORESIS, HIPERTENSIÓN, NICTURIA, HEMATURIA, GINECOMASTIA, IMPOTENCIA, DOLOR MAMARIO, FRACTURAS PATOLÓGICAS, EDEMA PERIFÉRICO, ANEMIA HIPOCRÓMICA, CEFALEA, NÁUSEA, DIARREA, EN OCASIONES MELENA, HEMORRAGIA RECTAL.', 'CONTRAINDICACIONES: HIPERSENSIBILIDAD AL FÁRMACO, INSUFICIENCIA HEPÁTICA.', 'INTERFIERE LA ACCIÓN DE CUMARÍNICOS POR LO QUE DEBERÁN PRACTICARSE TIEMPOS DE PROTOMBINA SERIADOS.', 'CARCINOMA METASTÁSICO DE PRÓSTATA.', 'ORAL\r\n\r\nADULTOS:\r\n\r\n50 MG CADA 24 HRS, A LA MISMA HORA.', 'ORAL\r\n\r\nADULTOS:\r\n\r\n50 MG CADA 24 HRS, A LA MISMA HORA', 'CADA TABLETA CONTIENE:\r\nBICALUTAMIDA		 50 MG', 'ENVASE CON 14 Y 28 TABLETAS.', 0, 10, 0, NULL, NULL),
