(1201, '5474', 'ERLOTINIB', 'COMPRIMIDO', '150 MG', 'ENVASE CON 30 COMPRIMIDOS', 'SEGUNDO NIVEL', 'ONCOLOGÍA', 'EL ERLOTINIB INHIBE EN FORMA INTENSA LA FOSFORILACIÓN INTRACELULAR DE HER1/EGFR, SE EXPRESA EN LA SUPERFICIE DE CÉLULAS NORMALES Y CÉLULAS CANCEROSAS. EN MODELOS PRECLÍNICOS, LA INHIBICIÓN DE LA EGFR-FOSFOTIROSINA PRODUCE ESTASIS Y MUERTE CELULAR.', 'D', 'ANOREXIA, DISNEA, TOS, DIARREA, NÁUSEA, VÓMITO, ERUPCIÓN, FATIGA', 'CONTRAINDICACIONES: HIPERSENSIBILIDAD AL MEDICAMENTO.', 'PUEDE INTERACTUAR CON MEDICAMENTOS INHIBIDORES  O INDUCTORES DE LAS ENZIMAS CYP3A4 Y EN MENOR GRADO CON CYP1A2, Y LA ISOFORMA PULMONAR CYP1A1. TAMBIÉN PUEDE INTERACTUAR CON MEDICAMENTOS QUE SEAN METABOLIZADOS POR DICHAS VÍAS ENZIMÁTICAS.', 'PACIENTES CON CÁNCER DE PULMÓN DE CÉLULAS NO PEQUEÑAS LOCALMENTE AVANZADO O METASTÁSICO, DESPUÉS DEL FRACASO A DOS LÍNEAS DE TRATAMIENTO PREVIO, SIN ANTECEDENTES DE TABAQUISMO, Y CON EXPRESIÓN DEL FACTOR DE CRECIMIENTO EPIDÉRMICO \r\nTIPO I (EGFR1/HER1).', 'ORAL.\r\n\r\nADULTOS:\r\n150 MG CADA 24 HORAS, UNA HORA ANTES O DOS HORAS DESPUES DE LOS ALIMENTOS.', 'ORAL', 'CADA COMPRIMIDO CONTIENE:\r\nCLORHIDRATO DE ERLOTINIB\r\nEQUIVALENTE A 					150 MG\r\nDE ERLOTINIB', 'ENVASE CON 30 COMPRIMIDOS.', 0, 10, 0, NULL, NULL),
(1202, '5443', 'ESTRAMUSTINA', 'CAPSULA', '140 MG', '100 CAPSULAS', 'SEGUNDO NIVEL', 'ONCOLOGÍA', 'ES UNA COMBINACIÓN DE 17 -BETA ESTRADIOL Y UNA MOSTAZA NITROGENADA, UNIDOS POR UN ENLACE DE CARBAMATO. SUPRIME LA LIBERACIÓN DE ANDRÓGENOS E INHIBE LA MITOSIS CELULAR EN METAFASE.', 'D', 'RETENCIÓN DE SODIO Y AGUA, ANEMIA, LEUCOPENIA, TROMBOCITOPENIA, TROMBOSIS, GINECOMASTÍA, DISMINUCIÓN DEL INTERÉS SEXUAL, DIARREA, VÓMITO, NÁUSEA.', 'CONTRAINDICACIONES: HIPERSENSIBILIDAD AL FÁRMACO. \r\nPRECAUCIONES: EN ALTERACIONES TROMBOEMBÓLICAS ACTIVAS, INSUFICIENCIA CARDIACA, ASMA RONQUIAL, EPILEPSIA, DETERIORO DE LA FUNCIÓN RENAL Y HEPÁTICA, VARICELA ACTUAL O RECIENTE, HERPES ZOSTER, DEPRESIÓN DE ???\0\0\0\0????', 'PUEDE AUMENTAR LA VIDA MEDIA, EFECTOS TÓXICOS Y TERAPÉUTICOS DE LA CORTICOIDES, ACCIÓN SINÉRGICA CON MEDICAMENTOS HEPATOTÓXICOS, DISMINUYE LA RESPUESTA A VACUNAS CON VIRUS MUERTOS, PUEDE INCREMENTAR LOS EFECTOS COLATERALES ADVERSOS DE LAS VACUNAS CON VIRU???\0\0\0\0?', 'TRATAMIENTO PALIATIVO DEL CARCINOMA PROSTÁTICO METASTÁSICO', 'ORAL\r\n\r\nADULTOS:\r\n\r\n600 MG/M2 DE SUPERFICIE CORPORAL/DIA, EN TRES TOMAS, UNA HORA ANTES O 2 HORAS DESPUES DE LOS ALIMENTOS.', 'ORAL\r\n\r\nADULTOS:\r\n\r\n600 MG/M2 DE SUPERFICIE CORPORAL/DIA, EN TRES TOMA', 'CADA CÁPSULA CONTIENE:\r\nFOSFATO SÓDICO DE ESTRAMUSTINA EQUIVALENTE A 	140 MG \r\nDE FOSFATO DE ESTRAMUSTINA.', 'ENVASE CON 100 CÁPSULAS', 0, 10, 0, NULL, NULL),
